import {publicNav,coordinatorShell,participantShell,images,skeleton,empty,toast,confirmDialog,wireCommon} from './components.js'
import {qs,qsa,escapeHtml,formatDate,getCurrentEventId,setBusy,statusClass,statusLabel} from './utils.js'
import {friendlyError,isConfigured} from './supabase.js'
import {supabase} from './supabase.js'
import {registerCoordinator,loginCoordinator,participantRegister,participantLogin,requireRole,logout} from './auth.js'
import {listEvents,getEvent,createEvent,dashboardStats,setRegistrationStatus} from './events.js'
import {listTeams,currentTeam,getParticipantPayload} from './teams.js'
import {setRoundStatus,announceRound,generateRoundTwo} from './rounds.js'
import {saveScore,leaderboard} from './scores.js'
import {publicWinners,publishWinners} from './winners.js'
import {minutesToSeconds,secondsToDisplayTime,secondsToInputValue,calculateScore} from './scoring.js'

const app=qs('#app'),page=document.body.dataset.page
const field=(name,label,type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input class="input" id="${name}" name="${name}" type="${type}" ${extra} required><span class="field-error" data-error="${name}"></span></div>`
const setupNotice=()=>!isConfigured?'<div class="locked-note"><strong>Supabase setup needed</strong><br><span class="muted">Add your project URL and anon key to <code>.env</code>, then run the included SQL.</span></div>':''
const authVisual=()=>`<aside class="auth-visual"><img src="${images.drone}" alt="Racing drone in motion"><div class="auth-quote"><span class="eyebrow">EVENTX / COMPETITION OS</span><h2>Every second counts.</h2></div></aside>`
const topbar=(label='Coordinator')=>`<div class="topbar"><span class="eyebrow">${label}</span><a class="btn btn-dark" href="/create-event.html">Create event</a></div>`

function bindLogout(){qsa('[data-logout]').forEach(x=>x.onclick=logout)}
function showError(error){toast(friendlyError(error))}

function renderHome(){app.innerHTML=`${publicNav()}<main><section class="hero container"><div class="hero-copy"><div><span class="eyebrow">Event management / 2026</span><h1 class="display">Compete smarter.<br><span>Perform better.</span></h1></div><div><p>Manage competitions, teams, rounds, scores and results in one powerful platform.</p><div class="button-row"><a class="btn btn-dark" href="/participant-register.html">Get started →</a><a class="btn" href="/participant-login.html">Team login</a></div></div></div><div class="hero-image"><img src="${images.hero}" alt="Advanced competition robot"><span class="hero-badge">Robotics · Drone racing · Live results</span><a class="scroll-dot" href="#explore" aria-label="Scroll to explore">↓</a></div></section><section class="section container" id="explore"><div class="section-intro"><h2 class="section-title">Competition management,<br>reimagined.</h2><p>From the first registration to the final podium, EVENTX gives coordinators a clear, reliable command center for teams, rounds, qualification, and live leaderboards.</p></div></section><section class="container cards-grid"><article class="visual-card"><img src="${images.robo}" alt="Robot competition"><div class="card-copy"><span class="pill">Precision racing</span><h3>ROBO RACE</h3><p>Configurable penalties, exact timing and instant rankings.</p></div></article><article class="visual-card"><img src="${images.drone}" alt="Drone in flight"><div class="card-copy"><span class="pill">FPV velocity</span><h3>DRONE RACE</h3><p>Track every touch, obstacle and bonus with confidence.</p></div></article><article class="visual-card"><img src="${images.event}" alt="Technology event"><div class="card-copy"><span class="pill">One platform</span><h3>COMPETITION EVENTS</h3><p>Registration, qualification and announcements in one flow.</p></div></article></section><section class="section container"><div class="stats"><div class="stat"><strong>50+</strong><span>Events managed</span></div><div class="stat"><strong>1.2K+</strong><span>Teams participated</span></div><div class="stat"><strong>4.5K+</strong><span>Rounds completed</span></div><div class="stat"><strong>98%</strong><span>Result accuracy</span></div></div></section><section class="container cta"><h2>Ready to run your next competition?</h2><a class="btn" href="/coordinator-register.html">Create event →</a></section></main><footer class="footer container"><a class="brand" href="/eventx.html">EVENTX<span></span></a><span>Competition, engineered.</span><span>© 2026 EVENTX</span></footer>`;wireCommon()}

function renderAuth(kind){const coordinator=kind.startsWith('coordinator'),register=kind.endsWith('register');const title=register?(coordinator?'Create your account.':'Enter the arena.'):(coordinator?'Welcome back.':'Welcome back, team.');let fields='';if(register&&coordinator)fields=field('username','Username','text','minlength="3" maxlength="30" pattern="[A-Za-z0-9_]+"')+field('name','Full name')+field('password','Password','password','minlength="8"');else if(register)fields=field('team_name','Team name')+field('phone_number','Phone number','tel','pattern="[0-9+ \\\\(\\\\)\\\\-]{7,20}"')+field('event_code','Event code');else if(coordinator)fields=field('username','Username')+field('password','Password','password');else fields=field('team_name','Team name')+field('team_code','Team ID / team code');const foot=register?(coordinator?`Already registered? <a href="/coordinator-login.html">Log in</a>`:`Already have a team? <a href="/participant-login.html">Log in</a>`):(coordinator?`New coordinator? <a href="/coordinator-register.html">Create account</a> · <a href="/participant-login.html">Team login</a>`:`Need to register? <a href="/participant-register.html">Register team</a> · <a href="/coordinator-login.html">Coordinator login</a>`);app.innerHTML=`<div class="auth-layout">${authVisual()}<main class="auth-main"><div class="auth-box"><a class="brand" href="/eventx.html">EVENTX<span></span></a><h1>${title}</h1><p>${register?'Build a competition people will remember.':'Your competition is waiting.'}</p>${setupNotice()}<form class="form-grid" id="auth-form">${fields}<button class="btn btn-dark" type="submit">${register?'Create account':'Log in'} →</button></form><p class="form-foot">${foot}</p></div></main></div>`;qs('#auth-form').onsubmit=async e=>{e.preventDefault();const btn=qs('button[type=submit]',e.currentTarget);setBusy(btn,true,register?'Creating…':'Logging in…');try{const data=Object.fromEntries(new FormData(e.currentTarget));if(coordinator&&register){await registerCoordinator(data);location.href='/coordinator-dashboard.html'}else if(coordinator){await loginCoordinator(data.username,data.password);location.href='/coordinator-dashboard.html'}else if(register){const team=await participantRegister(data);const authBox=qs('.auth-box');if(authBox){authBox.innerHTML=`<a class="brand" href="/eventx.html">EVENTX<span></span></a><div class="pill" style="margin-bottom:12px;background:rgba(34,197,94,0.1);color:#22c55e;border:1px solid rgba(34,197,94,0.2)">✓ Registration Successful</div><h1>${escapeHtml(team.team_name)}</h1><p>Your team has been registered for <strong>${escapeHtml(team.event_name||'the event')}</strong>.</p><div class="panel" style="margin:20px 0;text-align:left;background:var(--bg-elevated,#16181d)"><div style="font-size:0.85rem;color:var(--text-muted,#888);text-transform:uppercase;letter-spacing:0.05em">Your Team Code / ID</div><div style="font-size:1.8rem;font-weight:700;letter-spacing:0.05em;color:var(--text-bright,#fff);margin:6px 0">${escapeHtml(team.team_code)}</div><p style="font-size:0.85rem;color:var(--text-muted,#aaa);margin:0">⚠️ <strong>Save your Team Code.</strong> You will need your Team Name and Team Code to log in.</p></div><a class="btn btn-dark" style="width:100%;text-align:center" href="/participant-dashboard.html">Go to Participant Dashboard →</a>`}toast(`Registration successful! Team ID: ${team.team_code}`)}else{await participantLogin(data);location.href='/participant-dashboard.html'}}catch(error){showError(error)}finally{setBusy(btn,false)}}}

let coordinatorTimer=null;
let activeResync=null;

async function renderDashboard(){
  if(coordinatorTimer){clearInterval(coordinatorTimer);coordinatorTimer=null}
  app.innerHTML=coordinatorShell(`${topbar()}<section class="page-heading"><span class="eyebrow">Good day, Coordinator.</span><h1>Manage your events,<br><span class="muted">one competition at a time.</span></h1></section><div id="dashboard-data">${skeleton(4)}</div>`);
  bindLogout();
  if(!await requireRole('coordinator'))return;

  async function loadDashboardData(silent=false){
    try{
      const [stats,events]=await Promise.all([dashboardStats(),listEvents()]);
      const el=qs('#dashboard-data');
      if(el){
        el.innerHTML=`<div class="dashboard-stats"><div class="stat-card"><strong>${stats.events??0}</strong><span>Total events</span></div><div class="stat-card"><strong>${stats.teams??0}</strong><span>Total teams</span></div><div class="stat-card"><strong>${stats.active_events??0}</strong><span>Active events</span></div><div class="stat-card"><strong>${stats.completed_events??0}</strong><span>Completed events</span></div></div><div class="panel-head"><h2>Recent events</h2><a href="/events.html">View all →</a></div>${eventCards(events.slice(0,4))}`;
      }
    }catch(error){
      if(silent)console.error('[EventX] dashboard sync tick failed',error);
      if(!silent){
        qs('#dashboard-data').innerHTML=empty('Could not load dashboard',friendlyError(error));
      }
    }
  }

  await loadDashboardData(false);
  coordinatorTimer=setInterval(()=>loadDashboardData(true),8000);
  activeResync=()=>loadDashboardData(true);
  window.addEventListener('beforeunload',()=>clearInterval(coordinatorTimer));
}
function eventCards(events){if(!events.length)return empty('No events yet.','Create your first competition.');return `<div class="event-grid">${events.map((e,i)=>`<a class="event-card" href="/event.html?id=${e.id}"><img src="${i%2?images.drone:images.robo}" alt=""><div class="event-card-content"><span class="pill">${escapeHtml(e.event_code)}</span><h3>${escapeHtml(e.event_name)}</h3><p>${statusLabel(e.point_format)} · ${e.teams?.[0]?.count??0} teams</p><span class="btn">Open event →</span></div></a>`).join('')}</div>`}
async function renderEvents(){if(coordinatorTimer){clearInterval(coordinatorTimer);coordinatorTimer=null}app.innerHTML=coordinatorShell(`${topbar()}<section class="page-heading"><span class="eyebrow">Your portfolio</span><h1>Competition events.</h1></section><div id="events-list">${skeleton(3)}</div>`,'events');bindLogout();if(!await requireRole('coordinator'))return;try{qs('#events-list').innerHTML=eventCards(await listEvents())}catch(error){qs('#events-list').innerHTML=empty('Could not load events',friendlyError(error))}}
let participantTimer=null;

async function renderCreateEvent(){if(coordinatorTimer){clearInterval(coordinatorTimer);coordinatorTimer=null}app.innerHTML=coordinatorShell(`<div class="topbar"><a href="/events.html">← Events</a></div><section class="page-heading"><span class="eyebrow">New competition</span><h1>Create a new event.</h1></section><div class="panel" style="max-width:700px">${setupNotice()}<form class="form-grid" id="event-form">${field('event_name','Event name')}<div class="field"><label>Point format</label><div class="format-picker"><label class="format-option"><input type="radio" name="point_format" value="robo_race" checked><span><strong>Robo Race</strong><br><small class="muted">+ Line Touch · + Out of Line · + Complete Bot Exit · + Hand Touch · + Obstacle Skip</small></span></label><label class="format-option"><input type="radio" name="point_format" value="drone_race"><span><strong>Drone Race</strong><br><small class="muted">+ Ground Touch · + Obstacle Hit · + Obstacle Miss · − Perfect Landing</small></span></label></div></div><div class="code-display"><span>Event code</span><span>Generated securely on create</span></div><button class="btn btn-dark" type="submit">Create event →</button></form></div>`,'create');bindLogout();if(!await requireRole('coordinator'))return;qs('#event-form').onsubmit=async e=>{e.preventDefault();const btn=qs('button[type=submit]',e.currentTarget),data=Object.fromEntries(new FormData(e.currentTarget));setBusy(btn,true,'Creating event…');try{const event=await createEvent(data.event_name,data.point_format);toast('Event created successfully.');location.href=`/event.html?id=${event.id}`}catch(error){showError(error)}finally{setBusy(btn,false)}}}
async function renderCreateEvent(){if(coordinatorTimer){clearInterval(coordinatorTimer);coordinatorTimer=null}app.innerHTML=coordinatorShell(`<div class="topbar"><a href="/events.html">← Events</a></div><section class="page-heading"><span class="eyebrow">New competition</span><h1>Create a new event.</h1></section><div class="panel" style="max-width:700px">${setupNotice()}<form class="form-grid" id="event-form">${field('event_name','Event name')}<div class="field"><label>Point format</label><div class="format-picker"><label class="format-option"><input type="radio" name="point_format" value="robo_race" checked><span><strong>Robo Race</strong><br><small class="muted">+ Line Touch · + Out of Line · + Complete Bot Exit · + Hand Touch · + Obstacle Skip</small></span></label><label class="format-option"><input type="radio" name="point_format" value="drone_race"><span><strong>Drone Race</strong><br><small class="muted">+ Ground Touch · + Obstacle Hit · + Obstacle Miss · + Hand Touch · + Landing Miss</small></span></label></div></div><div class="code-display"><span>Event code</span><span>Generated securely on create</span></div><button class="btn btn-dark" type="submit">Create event →</button></form></div>`,'create');bindLogout();if(!await requireRole('coordinator'))return;qs('#event-form').onsubmit=async e=>{e.preventDefault();const btn=qs('button[type=submit]',e.currentTarget),data=Object.fromEntries(new FormData(e.currentTarget));setBusy(btn,true,'Creating event…');try{const event=await createEvent(data.event_name,data.point_format);toast('Event created successfully.');location.href=`/event.html?id=${event.id}`}catch(error){showError(error)}finally{setBusy(btn,false)}}}
async function renderEvent(initialTab='teams',defaultRoundId=null,defaultTeamId=null){if(coordinatorTimer){clearInterval(coordinatorTimer);coordinatorTimer=null}const id=getCurrentEventId();if(!id){app.innerHTML=coordinatorShell(`<div id="event-content">${empty('No event selected','The event link is missing or invalid. Go back to your events list and open an event again.')}<div class="button-row" style="margin-top:16px"><a class="btn btn-dark" href="/events.html">← Back to events</a></div></div>`,'events');bindLogout();return}if(!qs('#event-content')){app.innerHTML=coordinatorShell(`<div id="event-content">${skeleton(5)}</div>`,'events');bindLogout()}if(!await requireRole('coordinator'))return;try{const [event,teams,board]=await Promise.all([getEvent(id),listTeams(id),leaderboard(id)]);renderEventView(event,teams,board,initialTab,defaultRoundId,defaultTeamId)}catch(error){qs('#event-content').innerHTML=empty('Could not open event',friendlyError(error))}}
function renderEventView(event,teams,board,initialTab='teams',defaultRoundId=null,defaultTeamId=null){const rounds=[...event.rounds].sort((a,b)=>a.round_number-b.round_number),r1=rounds.find(r=>r.round_number===1),r2=rounds.find(r=>r.round_number===2);qs('#event-content').innerHTML=`<div class="topbar"><a href="/events.html">← All events</a><span class="pill">${escapeHtml(event.event_code)}</span></div><section class="page-heading"><span class="eyebrow">${statusLabel(event.point_format)}</span><h1>${escapeHtml(event.event_name)}</h1></section><nav class="tabs" aria-label="Event management"><button class="tab" data-tab="teams">Teams</button><button class="tab" data-tab="round1">Round 1</button><button class="tab" data-tab="round2">Round 2</button><button class="tab" data-tab="score">Score entry</button><button class="tab" data-tab="results">Results</button><button class="tab" data-tab="winners">Winner announcement</button></nav><div id="tab-panel"></div>`;const panel=qs('#tab-panel');const hasPublishedWinners=Boolean((event.winner_announcements?.length>0)||(event.status==='completed'));const show=(tab,roundId=null,teamId=null)=>{qsa('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));if(tab==='teams')panel.innerHTML=teamsPanel(teams,event);if(tab==='round1')panel.innerHTML=roundPanel(r1,teams,1);if(tab==='round2')panel.innerHTML=roundTwoPanel(r1,r2,teams,board);if(tab==='score')panel.innerHTML=scorePanel(event,rounds,teams,roundId||defaultRoundId,teamId||defaultTeamId);if(tab==='results')panel.innerHTML=resultsPanel(board,null,hasPublishedWinners);if(tab==='winners')panel.innerHTML=winnersPanel(board,event,hasPublishedWinners);bindEventActions(event,rounds,teams,board,show,tab)};qsa('.tab').forEach(x=>x.onclick=()=>show(x.dataset.tab));show(initialTab,defaultRoundId,defaultTeamId)}
function teamsPanel(teams,event){const closed=Boolean(event?.registration_closed);return `<div class="panel"><div class="panel-head"><div><h2>Registered teams</h2><p class="muted" style="margin:2px 0 0;font-size:0.85rem">Registration: <strong>${closed?'Closed':'Open'}</strong> — teams can ${closed?'no longer':'still'} register while rounds are in progress, until you change this.</p></div><div style="display:flex;gap:10px;align-items:center"><input class="input" id="team-search" placeholder="Search name or ID" style="max-width:260px"><button class="btn ${closed?'btn-dark':''}" data-toggle-registration="${event?.id||''}">${closed?'Reopen registration':'Close registration'}</button></div></div>${teams.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Team ID</th><th>Team</th><th>Phone</th><th>Registered</th></tr></thead><tbody>${teams.map(t=>`<tr data-team-row="${escapeHtml((t.team_name+' '+t.team_code).toLowerCase())}"><td>${escapeHtml(t.team_code)}</td><td><strong>${escapeHtml(t.team_name)}</strong></td><td>${escapeHtml(t.phone_number)}</td><td>${formatDate(t.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No teams registered yet.')}</div>`}
function roundPanel(round,teams,num){if(!round)return empty(`Round ${num} has not been generated.`);const locked=round.status==='locked';return `<div class="panel"><div class="panel-head"><div><span class="eyebrow">Round ${num}</span><h2>${statusLabel(round.status)}</h2></div><span class="${statusClass(round.status)}">${statusLabel(round.status)}</span></div>${locked?'<div class="locked-note"><strong>🔒 Round locked</strong><br>Scores can no longer be entered or changed for this round.</div>':''}${round.result_announced?`<div class="locked-note" style="border-color:#93c5fd;background:#eff6ff;color:#1e40af"><strong>📣 Result announced</strong><br>${locked?'This round is also locked.':'Scores remain editable until you explicitly lock this round.'}</div>`:''}<p class="muted">${teams.length} participating teams</p><div class="button-row">${round.status==='not_started'?'<button class="btn btn-dark" data-start-round="'+round.id+'">Start round</button>':''}${round.status!=='not_started'&&!locked?'<button class="btn" data-open-score>Enter scores</button>':''}${!round.result_announced?'<button class="btn" data-announce="'+round.id+'">Announce result</button>':''}${!locked&&round.status!=='not_started'?'<button class="btn btn-dark" data-lock-round="'+round.id+'">Lock round</button>':''}</div></div>`}
function roundTwoPanel(r1,r2,teams,board){const qualifiedTeams=r2?teams.filter(t=>t.round_teams?.some(x=>(x.round_id===r2.id||x.rounds?.round_number===2)&&x.qualified)):[];const statusHtml=r2?roundPanel(r2,qualifiedTeams,2):'';if(r2?.status==='locked')return statusHtml;return `${statusHtml}<div class="panel" style="margin-top:20px"><h2>${r2?'Adjust Round 2 Qualified Teams':'Generate Round 2'}</h2><p class="muted">Qualify all teams, select the fastest teams, or pick specific teams. This does not require Round 1 to be announced or locked.</p><form class="form-grid" id="round-two-form"><div class="format-picker"><label class="format-option"><input type="radio" name="method" value="automatic_top_n" checked><span><strong>Top N teams</strong><br><small class="muted">Qualify top ranked teams</small></span></label><label class="format-option"><input type="radio" name="method" value="manual"><span><strong>Manual selection</strong><br><small class="muted">Choose specific teams</small></span></label></div><div class="field"><label>Number of teams (Top N)</label><input class="input" name="top_n" type="number" min="1" max="${teams.length}" value="${teams.length}"></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><strong style="color:var(--ink)">Select Teams (${teams.length} total)</strong><button type="button" class="btn" style="padding:4px 10px;font-size:0.8rem" id="select-all-r2">Toggle all</button></div><div class="panel" style="background:#ffffff;border:1px solid var(--border,#D5D6DB);max-height:240px;overflow-y:auto;padding:8px 12px;border-radius:10px;color:#0f172a">${teams.map(t=>{const isQ=qualifiedTeams.some(qt=>qt.id===t.id);const b=board.find(x=>x.team_id===t.id);return `<label style="display:flex;align-items:center;gap:10px;padding:9px 8px;border-bottom:1px solid #f1f5f9;color:#0f172a;cursor:pointer"><input type="checkbox" name="team_ids" value="${t.id}" ${isQ||!r2?'checked':''}><span><strong style="color:#0f172a">${escapeHtml(t.team_code)}</strong> · <span style="color:#334155">${escapeHtml(t.team_name)}</span> <small style="color:#64748b">(${b?.round_1_score!=null?secondsToDisplayTime(b.round_1_score):'No score'})</small></span></label>`}).join('')}</div><button class="btn btn-dark" type="submit">${r2?'Update Round 2 teams':'Generate Round 2'} →</button></form></div>`}
function scorePanel(event,rounds,teams,defaultRoundId=null,defaultTeamId=null){const available=rounds.filter(r=>r.status!=='locked'&&r.status!=='not_started');if(!available.length)return rounds.some(r=>r.status==='locked')?empty('All active rounds are locked.','Scores can no longer be modified.'):empty('No round is active yet.','Start a round from its tab, then come back here to enter scores.');const activeRound=available.find(r=>r.id===defaultRoundId)||available[0];const roundTeams=teams.filter(t=>{if(activeRound.round_number===1)return !t.round_teams?.length||t.round_teams.some(rt=>(rt.round_id===activeRound.id||rt.rounds?.round_number===1)&&rt.qualified!==false);return t.round_teams?.some(rt=>(rt.round_id===activeRound.id||rt.rounds?.round_number===2)&&rt.qualified===true)});if(activeRound.round_number===2&&!roundTeams.length)return `<div class="score-layout"><div class="panel form-grid"><div class="field"><label>Round</label><select class="select" id="score-round-select" name="round_id">${available.map(r=>`<option value="${r.id}" ${r.id===activeRound.id?'selected':''}>Round ${r.round_number}</option>`).join('')}</select></div>${empty('No teams qualified for Round 2 yet.','Please go to the Round 2 tab and generate Round 2 qualifications first.')}</div></div>`;let selectedTeam=roundTeams.find(t=>t.id===defaultTeamId);if(!selectedTeam)selectedTeam=roundTeams.find(t=>!activeRound.scores?.some(s=>s.team_id===t.id))||roundTeams[0];const currentScore=activeRound.scores?.find(s=>s.team_id===selectedTeam?.id);const initialTime=currentScore?secondsToInputValue(currentScore.total_time_seconds):'';return `<div class="score-layout"><form class="panel form-grid" id="score-form"><div class="field"><label>Round</label><select class="select" id="score-round-select" name="round_id">${available.map(r=>`<option value="${r.id}" ${r.id===activeRound.id?'selected':''}>Round ${r.round_number}</option>`).join('')}</select></div><div class="field"><label>Team (${roundTeams.length} in this round)</label><select class="select" id="score-team-select" name="team_id">${roundTeams.map(t=>{const sc=activeRound.scores?.find(s=>s.team_id===t.id);const statusTag=sc?`✓ ${secondsToDisplayTime(sc.final_score_seconds)}`:'Pending';return `<option value="${t.id}" ${t.id===selectedTeam?.id?'selected':''}>${escapeHtml(t.team_code)} · ${escapeHtml(t.team_name)} (${statusTag})</option>`}).join('')}</select></div>${currentScore?`<div class="pill" style="margin-bottom:8px;background:rgba(59,130,246,0.1);color:#60a5fa;border:1px solid rgba(59,130,246,0.2)">✓ Score already entered: <strong>${secondsToDisplayTime(currentScore.final_score_seconds)}</strong> (${currentScore.final_score_seconds}s). Editing below will update this team's score.</div>`:''}<div class="field"><label for="total_time">Total time (minutes.seconds)</label><input class="input" id="total_time" name="total_time" type="text" inputmode="decimal" placeholder="3.56" value="${initialTime}" required><span class="field-error" data-error="total_time"></span></div>${event.scoring_rules.map(rule=>{const detail=currentScore?.score_details?.find(sd=>sd.rule_id===rule.id);const qty=detail?detail.quantity:0;return `<div class="field"><label for="rule_${rule.id}">${escapeHtml(rule.rule_name)} · ${rule.operation==='add'?'+':'−'}${rule.seconds}s</label><input class="input" id="rule_${rule.id}" name="rule_${rule.id}" type="number" min="0" value="${qty}" required><span class="field-error" data-error="rule_${rule.id}"></span></div>`}).join('')}<button class="btn btn-dark" type="submit">${currentScore?'Update score':'Save score'} →</button></form><aside class="result-card"><span class="eyebrow">Final time preview</span><div><strong id="final-seconds">${currentScore?currentScore.final_score_seconds:0}</strong> sec<br><small id="final-display">${currentScore?secondsToDisplayTime(currentScore.final_score_seconds):'0.00 min'}</small></div><div id="calculation" class="muted">${currentScore?`Calculated from ${secondsToDisplayTime(currentScore.total_time_seconds)} total time.`:'Enter a time to preview the calculation.'}</div></aside></div>`}
function formatFormulaBar(pointFormat){if(pointFormat==='drone_race'){return `<div class="format-rules-bar"><span style="font-size:11px;font-weight:700;color:var(--muted);letter-spacing:0.05em">DRONE RACE FORMAT:</span><span class="formula-pill formula-neg">+ Ground Touch (+5s)</span><span class="formula-pill formula-neg">+ Obstacle Hit (+4s)</span><span class="formula-pill formula-neg">+ Obstacle Miss (+8s)</span><span class="formula-pill formula-pos">− Perfect Landing (−8s)</span></div>`}return `<div class="format-rules-bar"><span style="font-size:11px;font-weight:700;color:var(--muted);letter-spacing:0.05em">ROBO RACE FORMAT:</span><span class="formula-pill formula-neg">+ Line Touch (+5s)</span><span class="formula-pill formula-neg">+ Complete Bot Exit (+20s)</span><span class="formula-pill formula-neg">+ Hand Touch (+10s)</span><span class="formula-pill formula-neg">+ Obstacle Skip (+25s)</span></div>`}
function formatFormulaBar(pointFormat){if(pointFormat==='drone_race'){return `<div class="format-rules-bar"><span style="font-size:11px;font-weight:700;color:var(--muted);letter-spacing:0.05em">DRONE RACE FORMAT:</span><span class="formula-pill formula-neg">+ Ground Touch (+5s)</span><span class="formula-pill formula-neg">+ Obstacle Hit (+4s)</span><span class="formula-pill formula-neg">+ Obstacle Miss (+8s)</span><span class="formula-pill formula-neg">+ Hand Touch (+5s)</span><span class="formula-pill formula-neg">+ Landing Miss (+5s)</span></div>`}return `<div class="format-rules-bar"><span style="font-size:11px;font-weight:700;color:var(--muted);letter-spacing:0.05em">ROBO RACE FORMAT:</span><span class="formula-pill formula-neg">+ Line Touch (+5s)</span><span class="formula-pill formula-neg">+ Complete Bot Exit (+20s)</span><span class="formula-pill formula-neg">+ Hand Touch (+10s)</span><span class="formula-pill formula-neg">+ Obstacle Skip (+25s)</span></div>`}

function resultsPanel(board,currentTeamId=null,hasPublishedWinners=false){if(!board.length)return empty('Results will appear here once scores are entered.');return `<div class="panel"><div class="panel-head"><div><h2>Leaderboard</h2><p class="muted" style="margin:0;font-size:0.85rem">Official rankings based on validated scores</p></div><span class="pill">${hasPublishedWinners?'Sealed podium':'Live database results'}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Rank</th><th>Team</th><th>Round 1</th><th>Round 2</th><th>Final Score</th></tr></thead><tbody>${board.map(x=>{const isMe=x.team_id===currentTeamId;let rowClass=isMe?'me ':'';let rankDisplay=`${String(x.rank).padStart(2,'0')}`;let winnerPill='';const showPodium=hasPublishedWinners||(x.winner_position!=null);if(showPodium&&x.rank===1){rowClass+='row-winner-1';rankDisplay=`<span class="rank-badge-podium badge-gold">🥇</span>`;winnerPill=`<span class="winner-pill pill-gold">🏆 Champion</span>`}else if(showPodium&&x.rank===2){rowClass+='row-winner-2';rankDisplay=`<span class="rank-badge-podium badge-silver">🥈</span>`;winnerPill=`<span class="winner-pill pill-silver">🥈 1st Runner Up</span>`}else if(showPodium&&x.rank===3){rowClass+='row-winner-3';rankDisplay=`<span class="rank-badge-podium badge-bronze">🥉</span>`;winnerPill=`<span class="winner-pill pill-bronze">🥉 2nd Runner Up</span>`}const r2Badge=x.is_round_2_qualified?`<span class="pill-qualified" style="margin-left:6px">✓ Round 2 Qualified</span>`:'';const meBadge=isMe?`<span class="pill" style="font-size:10px;padding:2px 8px;margin-left:6px;background:var(--ink);color:white">Your Team</span>`:'';return `<tr class="${rowClass.trim()}"><td class="rank">${rankDisplay}</td><td><strong>${escapeHtml(x.team_name)}</strong>${winnerPill}${meBadge}<br><small class="muted">${escapeHtml(x.team_code)}</small>${r2Badge}</td><td>${x.round_1_score!=null?secondsToDisplayTime(x.round_1_score):'Pending'}</td><td>${x.round_2_score!=null?secondsToDisplayTime(x.round_2_score):'Pending'}</td><td><strong>${x.final_score!=null?secondsToDisplayTime(x.final_score):'Pending'}</strong></td></tr>`}).join('')}</tbody></table></div></div>`}
function winnersPanel(board,event,hasPublishedWinners=false){
  if(!board.length)return empty('No leaderboard yet.','Enter scores to generate rankings first.');
  const rounds=[...(event.rounds||[])].sort((a,b)=>a.round_number-b.round_number);
  const highestRound=rounds[rounds.length-1];
  const isFinalAnnounced=Boolean(highestRound?.result_announced);
  const winnerCountOptions=[1,2,3,4].filter(n=>n<=board.length);
  const defaultCount=board.length>=3?3:(board.length||1);
  const canPublish=isFinalAnnounced&&!hasPublishedWinners;

  return `<div class="panel">
    <div class="panel-head">
      <div>
        <span class="eyebrow">Podium preview</span>
        <h2>Winner announcement</h2>
      </div>
      <div style="display:flex;align-items:center;gap:10px">
        <label for="winner-count" style="font-size:13px;font-weight:600">Winners to publish:</label>
        <select class="select" id="winner-count" style="max-width:130px;min-height:40px;padding:8px 12px" ${hasPublishedWinners?'disabled':''}>
          ${winnerCountOptions.map(n=>`<option value="${n}" ${n===defaultCount?'selected':''}>Top ${n}</option>`).join('')}
        </select>
      </div>
    </div>
    ${hasPublishedWinners?`<div class="locked-note" style="border-color:#86efac;background:#f0fdf4;color:#166534;margin-bottom:20px">
      <strong>✅ Winners Published</strong><br>
      The podium has been sealed and is publicly visible. Registration for this event is now closed.
    </div>`:''}
    ${!isFinalAnnounced&&!hasPublishedWinners?`<div class="locked-note" style="border-color:#fca5a5;background:#fef2f2;color:#991b1b;margin-bottom:20px">
      <strong>⚠️ Final Round Result Not Announced</strong><br>
      Please announce and lock the results of <strong>Round ${highestRound?.round_number||1}</strong> in the Round tab before publishing winners.
    </div>`:''}
    <div style="margin-bottom:20px">
      ${board.slice(0,4).map(x=>`<div class="winner-row">
        <span class="position">${x.rank===1?'🥇':(x.rank===2?'🥈':(x.rank===3?'🥉':String(x.rank).padStart(2,'0')))}</span>
        <div>
          <h3 style="font-size:1.4rem;margin:0 0 2px">${escapeHtml(x.team_name)}</h3>
          <span class="muted">${escapeHtml(x.team_code)} · Score: <strong>${x.final_score!=null?secondsToDisplayTime(x.final_score):'Pending'}</strong></span>
        </div>
        <span class="pill ${x.rank===1?'pill-gold':(x.rank===2?'pill-silver':(x.rank===3?'pill-bronze':''))}">${x.rank===1?'Champion':(x.rank===2?'1st Runner Up':(x.rank===3?'2nd Runner Up':'Top 4'))}</span>
      </div>`).join('')}
    </div>
    <p class="muted" style="margin:0 0 12px;font-size:0.85rem">${hasPublishedWinners?'Winners are publicly visible on the Winners page.':'Publishing seals the podium publicly and automatically closes registration for this event.'}</p>
    <button class="btn btn-dark" data-publish="${event.id}" ${!canPublish?'disabled title="'+(hasPublishedWinners?'Already published':'Announce the final round result first')+'"':''} style="${!canPublish?'opacity:0.45;cursor:not-allowed':''}">
      ${hasPublishedWinners?'✅ Winners Published':'Publish winners →'}
    </button>
  </div>`;
}
function bindEventActions(event,rounds,teams,board,show,currentTab='teams'){const search=qs('#team-search');if(search)search.oninput=()=>qsa('[data-team-row]').forEach(r=>r.hidden=!r.dataset.teamRow.includes(search.value.toLowerCase()));qsa('[data-start-round]').forEach(btn=>btn.onclick=async()=>{try{await setRoundStatus(btn.dataset.startRound,'active');toast('Round started.');renderEvent(currentTab)}catch(e){showError(e)}});qs('[data-open-score]')?.addEventListener('click',()=>show('score'));qsa('[data-announce]').forEach(btn=>btn.onclick=async()=>{if(!await confirmDialog({title:'Announce round result?',message:'This publishes the result as official. Scores remain editable until you separately lock this round.',confirmText:'Announce result'}))return;try{await announceRound(btn.dataset.announce);toast('Result announced. Scores are still editable until you lock this round.');renderEvent(currentTab)}catch(e){showError(e)}});qsa('[data-lock-round]').forEach(btn=>btn.onclick=async()=>{if(!await confirmDialog({title:'Lock this round?',message:'Locking is final: scores can no longer be entered or changed for this round afterward.',confirmText:'Lock round'}))return;try{await setRoundStatus(btn.dataset.lockRound,'locked');toast('Round locked. Scores can no longer be changed.');renderEvent(currentTab)}catch(e){showError(e)}});qs('[data-toggle-registration]')?.addEventListener('click',async e=>{const closed=!event.registration_closed;if(!await confirmDialog({title:closed?'Close registration?':'Reopen registration?',message:closed?'New teams will no longer be able to register for this event until you reopen it.':'New teams will be able to register for this event again.',confirmText:closed?'Close registration':'Reopen registration'}))return;const btn=e.currentTarget;try{await setRegistrationStatus(event.id,closed);toast(closed?'Registration closed.':'Registration reopened.');renderEvent('teams')}catch(er){showError(er)}});const selectAllBtn=qs('#select-all-r2');if(selectAllBtn){selectAllBtn.onclick=()=>{const boxes=qsa('input[name="team_ids"]');const allChecked=boxes.every(b=>b.checked);boxes.forEach(b=>b.checked=!allChecked)}}const r2form=qs('#round-two-form');if(r2form)r2form.onsubmit=async e=>{e.preventDefault();const btn=qs('button[type=submit]',r2form);setBusy(btn,true,'Generating Round 2…');const fd=new FormData(e.currentTarget),method=fd.get('method');try{await generateRoundTwo(event.id,method,fd.get('top_n'),fd.getAll('team_ids'));toast('Round 2 qualified teams updated.');renderEvent('round2')}catch(er){showError(er)}finally{setBusy(btn,false)}};const roundSelect=qs('#score-round-select');if(roundSelect){roundSelect.onchange=()=>show('score',roundSelect.value)}const teamSelect=qs('#score-team-select');if(teamSelect){teamSelect.onchange=()=>show('score',roundSelect?roundSelect.value:null,teamSelect.value)}const sf=qs('#score-form');if(sf){const calculate=()=>{try{const total=minutesToSeconds(sf.total_time.value),rules=event.scoring_rules.map(r=>({id:r.id,key:`rule_${r.id}`,name:r.rule_name,seconds:r.seconds,operation:r.operation})),values=Object.fromEntries(new FormData(sf)),result=calculateScore(total,rules,values);qs('#final-seconds').textContent=result.finalScoreSeconds;qs('#final-display').textContent=secondsToDisplayTime(result.finalScoreSeconds);qs('#calculation').textContent=result.details.map(x=>`${x.operation==='add'?'+':'−'} ${x.calculatedSeconds}s ${x.name}`).join(' · ')}catch{}};sf.oninput=calculate;sf.onsubmit=async e=>{e.preventDefault();const btn=qs('button[type=submit]',sf);setBusy(btn,true,'Saving score…');try{const fd=Object.fromEntries(new FormData(sf)),total=minutesToSeconds(fd.total_time),rules=event.scoring_rules.map(r=>({id:r.id,key:`rule_${r.id}`,rule_key:r.rule_key,name:r.rule_name,seconds:r.seconds,operation:r.operation})),result=calculateScore(total,rules,fd);await saveScore({roundId:fd.round_id,teamId:fd.team_id,totalTimeSeconds:total,details:result.details});toast('Score saved successfully.');const [freshEvent,freshTeams]=await Promise.all([getEvent(event.id),listTeams(event.id)]);const activeR=freshEvent.rounds.find(r=>r.id===fd.round_id);const roundTeams=freshTeams.filter(t=>{if(activeR.round_number===1)return true;return t.round_teams?.some(rt=>rt.round_id===activeR.id&&rt.qualified)});const unscored=roundTeams.find(t=>!activeR.scores?.some(s=>s.team_id===t.id));const nextTeamId=unscored?unscored.id:null;await renderEvent('score',fd.round_id,nextTeamId)}catch(er){showError(er)}finally{setBusy(btn,false)}}}const publish=qs('[data-publish]');if(publish)publish.onclick=async()=>{if(!await confirmDialog({title:'Publish the final winners?',message:'This will make the announcement visible publicly and automatically close registration for this event.',confirmText:'Publish winners'}))return;try{await publishWinners(event.id,Number(qs('#winner-count').value));toast('Winners published successfully. Registration is now closed.');renderEvent('winners')}catch(e){showError(e)}}}

async function renderParticipant(){
  if(participantTimer){clearInterval(participantTimer);participantTimer=null}
  app.innerHTML=participantShell(`<div id="participant-content">${skeleton(4)}</div>`);
  bindLogout();
  if(!await requireRole('participant'))return;

  async function syncParticipantData(isAuto=false){
    try{
      const payload=await getParticipantPayload();
      const team=payload.team,board=payload.leaderboard||[],winners=payload.winners||[],round2Configured=payload.round_2_configured;
      const mine=board.find(x=>x.team_id===team.id);
      const rounds=[...(team.events?.rounds||[])].sort((a,b)=>a.round_number-b.round_number);
      const r1=rounds.find(r=>r.round_number===1),r2=rounds.find(r=>r.round_number===2);

      // Winner Section & Podium
      let winnerAnnouncementHtml='';
      if(winners.length>0){
        const p1=winners.find(w=>w.winner_position===1);
        const p2=winners.find(w=>w.winner_position===2);
        const p3=winners.find(w=>w.winner_position===3);

        const myWinPos=team.winner_position;
        const myWinnerBanner=myWinPos?`<div class="winner-personal-card"><span style="font-size:2.2rem">🏆</span><div><div style="font-size:0.85rem;text-transform:uppercase;letter-spacing:0.08em;color:#fef08a">Championship Recognition</div><strong>Congratulations! Your team won Position #${myWinPos}!</strong></div></div>`:''

        winnerAnnouncementHtml=`<section class="winner-hero-banner"><span class="eyebrow" style="color:#fde047">OFFICIAL PODIUM ANNOUNCEMENT</span><h2>🏆 Winner Announcement</h2><p>The competition coordinator has published the official results and sealed the championship podium.</p>${myWinnerBanner}<div class="podium-grid">${p1?`<div class="podium-card podium-1"><div class="podium-rank-icon">🥇</div><div class="podium-title">Champion · 1st Place</div><div class="podium-team">${escapeHtml(p1.team_name)}</div><div class="podium-code">${escapeHtml(p1.team_code)}</div><div class="podium-score">${p1.final_score!=null?secondsToDisplayTime(p1.final_score):'Winner'}</div></div>`:''}${p2?`<div class="podium-card podium-2"><div class="podium-rank-icon">🥈</div><div class="podium-title">1st Runner Up · 2nd Place</div><div class="podium-team">${escapeHtml(p2.team_name)}</div><div class="podium-code">${escapeHtml(p2.team_code)}</div><div class="podium-score">${p2.final_score!=null?secondsToDisplayTime(p2.final_score):'Finalist'}</div></div>`:''}${p3?`<div class="podium-card podium-3"><div class="podium-rank-icon">🥉</div><div class="podium-title">2nd Runner Up · 3rd Place</div><div class="podium-team">${escapeHtml(p3.team_name)}</div><div class="podium-code">${escapeHtml(p3.team_code)}</div><div class="podium-score">${p3.final_score!=null?secondsToDisplayTime(p3.final_score):'Finalist'}</div></div>`:''}</div></section>`;
      }

      // Round 1 Highlight Card
      let r1HighlightHtml='';
      if(r1?.status==='locked'){
        r1HighlightHtml=`<div class="round-highlight-card completed"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px"><div><span class="round-badge badge-completed">✓ Round 1 Locked</span><h3 style="margin:8px 0 2px;font-size:1.35rem">Round 1 Results Locked</h3><p class="muted" style="margin:0;font-size:0.88rem">All Round 1 scores are final and can no longer change.</p></div><div style="text-align:right"><span class="eyebrow">Your Round 1 Score</span><strong style="font-size:1.6rem;font-family:Manrope,sans-serif;display:block;color:var(--ink)">${mine?.round_1_score!=null?secondsToDisplayTime(mine.round_1_score):'Pending'}</strong></div></div></div>`;
      }else if(r1?.result_announced){
        r1HighlightHtml=`<div class="round-highlight-card active"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px"><div><span class="round-badge badge-active">📣 Result Announced</span><h3 style="margin:8px 0 2px;font-size:1.35rem">Round 1 Result Announced</h3><p class="muted" style="margin:0;font-size:0.88rem">Scores may still be updated by the coordinator until this round is locked.</p></div><div style="text-align:right"><span class="eyebrow">Your Round 1 Score</span><strong style="font-size:1.6rem;font-family:Manrope,sans-serif;display:block;color:var(--ink)">${mine?.round_1_score!=null?secondsToDisplayTime(mine.round_1_score):'Pending'}</strong></div></div></div>`;
      }else if(r1?.status==='active'){
        r1HighlightHtml=`<div class="round-highlight-card active"><span class="round-badge badge-active">⚡ Round 1 In Progress</span><h3 style="margin:8px 0 2px;font-size:1.35rem">Round 1 Scoring Active</h3><p class="muted" style="margin:0;font-size:0.88rem">Track runs are in progress. Live scores will update dynamically.</p></div>`;
      }else{
        r1HighlightHtml=`<div class="round-highlight-card"><span class="round-badge badge-pending">⏱ Round 1 Pending</span><h3 style="margin:8px 0 2px;font-size:1.35rem">Round 1 Not Started</h3><p class="muted" style="margin:0;font-size:0.88rem">Waiting for coordinator to launch Round 1.</p></div>`;
      }

      const formatHtml=formatFormulaBar(team.events?.point_format);

      qs('#participant-content').innerHTML=`
        ${winnerAnnouncementHtml}

        <section class="page-heading section" style="padding-top:20px;padding-bottom:30px">
          <span class="eyebrow">Participant Command Center</span>
          <h1>${escapeHtml(team.team_name)}.</h1>
          <p class="muted">Live updates for your rounds, qualification status, and official leaderboard.</p>
          ${formatHtml}
        </section>

        <section class="round-cards-grid">
          ${r1HighlightHtml}
          ${r2?`<div class="round-highlight-card ${r2.status==='locked'?'completed':(r2.status==='active'?'active':'')}">
            <span class="round-badge ${r2.status==='locked'?'badge-completed':(r2.status==='active'?'badge-active':'badge-pending')}">
              ${r2.status==='locked'?'✓ Round 2 Locked':(r2.status==='active'?(r2.result_announced?'📣 Result Announced':'⚡ Round 2 Active'):'Round 2 '+statusLabel(r2.status))}
            </span>
            <h3 style="margin:8px 0 2px;font-size:1.35rem">Round 2 Final</h3>
            <p class="muted" style="margin:0;font-size:0.88rem">${team.is_round_2_qualified?'Your team is competing in this round.':'Round 2 for qualified finalists.'}</p>
            ${mine?.round_2_score!=null?`<div style="margin-top:12px"><span class="eyebrow">Your Round 2 Score</span><strong style="font-size:1.4rem;display:block;font-family:Manrope">${secondsToDisplayTime(mine.round_2_score)}</strong></div>`:''}
          </div>`:''}
        </section>

        <section class="panel">
          <div class="panel-head"><h2>Team details</h2><span class="pill">Active Participant</span></div>
          <div class="dashboard-stats">
            <div><small class="muted">Team ID</small><strong style="display:block">${escapeHtml(team.team_code)}</strong></div>
            <div><small class="muted">Event</small><strong style="display:block">${escapeHtml(team.events?.event_name||'')}</strong></div>
            <div><small class="muted">Event code</small><strong style="display:block">${escapeHtml(team.events?.event_code||'')}</strong></div>
            <div><small class="muted">Format</small><strong style="display:block">${statusLabel(team.events?.point_format)}</strong></div>
          </div>
        </section>

        <section class="panel">
          <div class="panel-head">
            <div>
              <h2>Round status overview</h2>
              <p class="muted" style="margin:0;font-size:0.85rem">Real-time status of each competition stage</p>
            </div>
          </div>
          ${rounds.map(r=>`<div class="winner-row"><span class="position">0${r.round_number}</span><div><h3>Round ${r.round_number}</h3><span class="${statusClass(r.status)}">${statusLabel(r.status)}${r.result_announced?(r.status==='locked'?' · Announced & Locked':' · Result Announced'):''}</span></div></div>`).join('')||empty('No rounds yet.')}
        </section>

        <section class="panel">
          <div class="panel-head">
            <div>
              <h2>Live Leaderboard</h2>
              <p class="muted">${mine?`Your rank: <strong>#${mine.rank}</strong> · Total score: <strong>${mine.final_score!=null?secondsToDisplayTime(mine.final_score):'Pending'}</strong>`:''}</p>
            </div>
            <span class="pill">Certified results</span>
          </div>
          ${resultsPanel(board,team.id,winners.length>0)}
        </section>
      `;

    }catch(error){
      if(isAuto){
        console.error('[EventX] live sync tick failed',error);
        // If the session is no longer valid, stop the polling interval and redirect.
        if(error?.message==='not_authorized'||error?.message?.includes('not_authorized')){
          if(participantTimer){clearInterval(participantTimer);participantTimer=null}
          location.href='/participant-login.html';
          return;
        }
      } else {
        qs('#participant-content').innerHTML=empty('Could not load your dashboard',friendlyError(error));
      }
    }
  }

  await syncParticipantData(false);
  participantTimer=setInterval(()=>syncParticipantData(true),5000);
  activeResync=()=>syncParticipantData(true);
  window.addEventListener('beforeunload',()=>clearInterval(participantTimer));
}

async function renderWinners(){app.innerHTML=`${publicNav()}<main class="container section"><section class="page-heading"><span class="eyebrow">Hall of victory</span><h1>Winners.</h1><p class="muted">Published competition results, sealed by the coordinator.</p></section><div id="winners-list" style="margin-top:70px">${skeleton(4)}</div></main>`;wireCommon();if(!isConfigured){qs('#winners-list').innerHTML=empty('Connect Supabase to see published winners.');return}try{const rows=await publicWinners(),groups=rows.reduce((all,row)=>{(all[row.event_id]??=[]).push(row);return all},{});qs('#winners-list').innerHTML=rows.length?Object.values(groups).map(group=>`<section class="panel" style="margin-bottom:30px"><span class="eyebrow">${escapeHtml(statusLabel(group[0].point_format))}</span><h2 class="section-title" style="margin:14px 0 30px">${escapeHtml(group[0].event_name)}</h2>${group.map(x=>`<div class="winner-row"><span class="position">${String(x.winner_position).padStart(2,'0')}</span><div><h3>${escapeHtml(x.team_name)}</h3><span class="muted">${x.winner_position===1?'Champion':'Finalist'}</span></div><span class="pill">${x.winner_position===1?'Winner':'Top '+group.length}</span></div>`).join('')}</section>`).join(''):empty('No winners published yet.','The podium will appear here after a coordinator publishes final results.')}catch(e){qs('#winners-list').innerHTML=empty('Could not load winners',friendlyError(e))}}

async function renderProfile(){app.innerHTML=coordinatorShell(`<div class="topbar"><span class="eyebrow">Account</span></div><section class="page-heading"><h1>Your profile.</h1></section><div id="profile-data">${skeleton(2)}</div>`,'profile');bindLogout();const user=await requireRole('coordinator');if(!user)return;try{const {data,error}=await supabase.from('coordinators').select('username,name').eq('id',user.id).single();if(error)throw error;qs('#profile-data').innerHTML=`<div class="panel" style="max-width:650px"><div class="form-grid"><div class="field"><label>Name</label><div class="input">${escapeHtml(data.name)}</div></div><div class="field"><label>Username</label><div class="input">${escapeHtml(data.username)}</div></div></div></div>`}catch(e){qs('#profile-data').innerHTML=empty('Could not load profile',friendlyError(e))}}

window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()})
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){if(supabase)supabase.auth.getSession().catch(()=>{});activeResync?.()}})

const routes={home:renderHome,winners:renderWinners,'coordinator-login':()=>renderAuth('coordinator-login'),'coordinator-register':()=>renderAuth('coordinator-register'),'participant-login':()=>renderAuth('participant-login'),'participant-register':()=>renderAuth('participant-register'),'coordinator-dashboard':renderDashboard,events:renderEvents,'create-event':renderCreateEvent,event:renderEvent,'participant-dashboard':renderParticipant,profile:renderProfile}
routes[page]?.()
